sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }


    var pattern = /^\(\d{3}\)\s\d{3}-\d{4}$/; //(xxx) xxx-xxxx
    var phone = newValue;
    if (!pattern.test(phone)) {
        phone = phone.replace(/\D/g, '');
        var regex = /^\d{10}$/;
        var is_valid = regex.test(phone);
        if (!is_valid) {
            g_form.clearValue('external_customer_contact');
            g_form.showFieldMsg('external_customer_contact', 'Please enter valid phone number ie. "123-456-7890"', 'error');
        }
    }


}
